import { join } from "../../deps/path.js";
import { mkdirSync, readDirSync, removeSync, statSync } from "../services/fs.js";
/** Ensure a directory is empty */
export function emptyDir(dir) {
    try {
        for (const item of readDirSync(dir)) {
            removeSync(join(dir, item.name), true);
        }
    }
    catch (error) {
        if (error.code !== "not-found") {
            throw error;
        }
        // if not exist. then create it
        mkdirSync(dir, true);
    }
}
/** Ensure a directory exists */
export function ensureDir(dir) {
    try {
        const fileInfo = statSync(dir);
        if (!fileInfo.isDirectory) {
            throw new Error(`Failed to ensure directory exists: ${dir} already exists but it's not a directory`);
        }
        return;
    }
    catch (error) {
        if (error.code !== "not-found") {
            throw error;
        }
        mkdirSync(dir, true);
    }
}
